CREATE TABLE IF NOT EXISTS catalogo.marcas (
 tenant_id uuid NOT NULL REFERENCES plataforma.tenants(id),slug text NOT NULL CHECK(slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND length(slug)<=80),
 nombre text NOT NULL CHECK(length(btrim(nombre)) BETWEEN 1 AND 160),descripcion text NOT NULL DEFAULT '' CHECK(length(descripcion)<=1000),
 logo_url text CHECK(logo_url IS NULL OR logo_url ~ '^(https://|/images/)'),sitio_url text CHECK(sitio_url IS NULL OR sitio_url ~ '^https://'),
 estado text NOT NULL DEFAULT 'ACTIVE' CHECK(estado IN ('ACTIVE','INACTIVE')),creado_por uuid NOT NULL REFERENCES plataforma.users(id),
 creado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),actualizado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),version bigint NOT NULL DEFAULT 1,
 PRIMARY KEY(tenant_id,slug)
);
ALTER TABLE catalogo.marcas ENABLE ROW LEVEL SECURITY;REVOKE ALL ON catalogo.marcas FROM PUBLIC,mastererp_app;
ALTER TABLE catalogo.productos ADD COLUMN IF NOT EXISTS marca_ref text;
INSERT INTO plataforma.permissions(code,description) VALUES ('catalog.brands.read','Read Catalog brands'),('catalog.brands.write','Create and update Catalog brands') ON CONFLICT(code) DO NOTHING;
CREATE OR REPLACE FUNCTION catalogo.marcas_leer(p_slug text DEFAULT NULL,p_estado text DEFAULT NULL,p_limit integer DEFAULT 100) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$
DECLARE result jsonb;BEGIN IF p_limit NOT BETWEEN 1 AND 101 OR (p_estado IS NOT NULL AND p_estado NOT IN ('ACTIVE','INACTIVE')) THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.brands.read') IS NOT TRUE THEN RAISE EXCEPTION 'Brand access denied' USING ERRCODE='42501';END IF;
SELECT COALESCE(jsonb_agg(item ORDER BY nombre,slug),'[]') INTO result FROM (SELECT m.nombre,m.slug,jsonb_build_object('slug',m.slug,'name',m.nombre,'description',m.descripcion,'logo_url',m.logo_url,'website_url',m.sitio_url,'status',m.estado,'product_count',(SELECT count(*) FROM catalogo.productos p WHERE p.tenant_id=m.tenant_id AND p.marca_ref=m.slug),'version',m.version,'updated_at',m.actualizado_en) item FROM catalogo.marcas m WHERE m.tenant_id=plataforma.current_app_tenant_id() AND (p_slug IS NULL OR m.slug=p_slug) AND (p_estado IS NULL OR m.estado=p_estado) ORDER BY m.nombre,m.slug LIMIT p_limit)q;
IF p_slug IS NOT NULL AND jsonb_array_length(result)=0 THEN RAISE EXCEPTION 'Brand not found' USING ERRCODE='P0002';END IF;RETURN CASE WHEN p_slug IS NULL THEN result ELSE result->0 END;END $$;
CREATE OR REPLACE FUNCTION catalogo.marca_crear(p_slug text,p_nombre text,p_descripcion text,p_logo text,p_sitio text,p_key varchar) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,auditoria,pg_temp AS $$
DECLARE actor uuid:=plataforma.current_app_user_id();tenant uuid:=plataforma.current_app_tenant_id();op text:='catalog.brands.create';corr uuid;fp text;cached plataforma.idempotency_keys%ROWTYPE;response jsonb;BEGIN
IF p_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' OR length(p_slug)>80 OR length(btrim(p_nombre)) NOT BETWEEN 1 AND 160 OR COALESCE(length(p_descripcion),0)>1000 OR length(p_key) NOT BETWEEN 1 AND 128 OR (p_logo IS NOT NULL AND p_logo !~ '^(https://|/images/)') OR (p_sitio IS NOT NULL AND p_sitio !~ '^https://') THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;
IF plataforma.has_current_tenant_capability('erp.catalog','catalog.brands.write') IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM op THEN RAISE EXCEPTION 'Brand creation denied' USING ERRCODE='42501';END IF;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;fp:=encode(public.digest(jsonb_build_array(p_slug,p_nombre,p_descripcion,p_logo,p_sitio)::text,'sha256'),'hex');PERFORM pg_advisory_xact_lock(hashtextextended(p_key,0));SELECT * INTO cached FROM plataforma.idempotency_keys WHERE idempotency_key=p_key;IF FOUND THEN IF cached.actor_user_id<>actor OR cached.request_tenant_id<>tenant OR cached.operation<>op OR cached.request_fingerprint<>fp THEN RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='23505';END IF;RETURN cached.response_payload;END IF;
INSERT INTO catalogo.marcas(tenant_id,slug,nombre,descripcion,logo_url,sitio_url,creado_por) VALUES(tenant,p_slug,btrim(p_nombre),COALESCE(btrim(p_descripcion),''),NULLIF(btrim(p_logo),''),NULLIF(btrim(p_sitio),''),actor);response:=catalogo.marcas_leer(p_slug);INSERT INTO plataforma.idempotency_keys(idempotency_key,actor_user_id,operation,request_fingerprint,request_tenant_id,response_payload) VALUES(p_key,actor,op,fp,tenant,response);INSERT INTO auditoria.events(tenant_id,actor_user_id,module_code,entity_type,entity_id,action,correlation_id,metadata) VALUES(tenant,actor,'2.1.4-brands','marca',gen_random_uuid(),op,corr,jsonb_build_object('slug',p_slug));RETURN response;END $$;
CREATE OR REPLACE FUNCTION catalogo.marca_actualizar(p_slug text,p_version bigint,p_cambios jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,auditoria,pg_temp AS $$
DECLARE tenant uuid:=plataforma.current_app_tenant_id();actor uuid:=plataforma.current_app_user_id();current catalogo.marcas%ROWTYPE;corr uuid;key text;BEGIN IF p_version IS NULL OR jsonb_typeof(p_cambios)<>'object' OR p_cambios='{}' THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;FOR key IN SELECT jsonb_object_keys(p_cambios) LOOP IF key NOT IN ('name','description','logo_url','website_url','status') THEN RAISE EXCEPTION 'Unsupported brand field' USING ERRCODE='22023';END IF;END LOOP;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.brands.write') IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM 'catalog.brands.update' THEN RAISE EXCEPTION 'Brand update denied' USING ERRCODE='42501';END IF;SELECT * INTO current FROM catalogo.marcas WHERE tenant_id=tenant AND slug=p_slug FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Brand not found' USING ERRCODE='P0002';END IF;IF current.version<>p_version THEN RAISE EXCEPTION 'Stale brand version' USING ERRCODE='40001';END IF;
UPDATE catalogo.marcas SET nombre=CASE WHEN p_cambios?'name' THEN btrim(p_cambios->>'name') ELSE nombre END,descripcion=CASE WHEN p_cambios?'description' THEN COALESCE(btrim(p_cambios->>'description'),'') ELSE descripcion END,logo_url=CASE WHEN p_cambios?'logo_url' THEN NULLIF(btrim(p_cambios->>'logo_url'),'') ELSE logo_url END,sitio_url=CASE WHEN p_cambios?'website_url' THEN NULLIF(btrim(p_cambios->>'website_url'),'') ELSE sitio_url END,estado=CASE WHEN p_cambios?'status' THEN p_cambios->>'status' ELSE estado END,version=version+1,actualizado_en=transaction_timestamp() WHERE tenant_id=tenant AND slug=p_slug;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;INSERT INTO auditoria.events(tenant_id,actor_user_id,module_code,entity_type,entity_id,action,correlation_id,metadata) VALUES(tenant,actor,'2.1.4-brands','marca',gen_random_uuid(),'catalog.brands.update',corr,jsonb_build_object('slug',p_slug));RETURN catalogo.marcas_leer(p_slug);END $$;
REVOKE ALL ON FUNCTION catalogo.marcas_leer(text,text,integer),catalogo.marca_crear(text,text,text,text,text,varchar),catalogo.marca_actualizar(text,bigint,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION catalogo.marcas_leer(text,text,integer),catalogo.marca_crear(text,text,text,text,text,varchar),catalogo.marca_actualizar(text,bigint,jsonb) TO mastererp_app;
